import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BiXHgXAn.js";const k=JSON.parse('{"title":"Watch mode","description":"Re-run a task automatically whenever its sources change.","frontmatter":{"title":"Watch mode","description":"Re-run a task automatically whenever its sources change.","section":"Guide","docType":"guide","outline":"deep"},"headers":[],"relativePath":"docs/guide/watch.md","filePath":"next/docs/guide/watch.md"}'),n={name:"docs/guide/watch.md"};function h(l,s,p,r,o,c){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="watch-mode" tabindex="-1">Watch mode <a class="header-anchor" href="#watch-mode" aria-label="Permalink to &quot;Watch mode&quot;">​</a></h1><p>Use <code>--watch</code> (or <code>-w</code>) to keep a task running and rerun it when its source files change. For a Go project:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;**/*.go&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go.mod</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go.sum</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go build ./...</span></span></code></pre></div><p>Run <code>task --watch build</code>, edit a Go file, and save it to trigger another build. Press Ctrl+C to stop watching.</p><p>Watch mode detects changes; <a href="./up-to-date">up-to-date checks</a> decide whether the task&#39;s commands need to run. Both use the same <code>sources</code>.</p><h2 id="enable-watching-by-default" tabindex="-1">Enable watching by default <a class="header-anchor" href="#enable-watching-by-default" aria-label="Permalink to &quot;Enable watching by default&quot;">​</a></h2><p>Set <code>watch: true</code> on a task if its normal CLI use should start a watcher:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    watch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;**/*.go&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">go build ./...</span></span></code></pre></div><p>Now <code>task build</code> starts watch mode. The <code>watch</code> setting applies when the task is called from the CLI; calls from another task through <code>cmds</code> or <code>deps</code> do not start a watcher.</p><h2 id="combine-rapid-changes" tabindex="-1">Combine rapid changes <a class="header-anchor" href="#combine-rapid-changes" aria-label="Permalink to &quot;Combine rapid changes&quot;">​</a></h2><p>The default watch interval is 100 milliseconds. Increase it if saving several files produces duplicate events:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --interval=500ms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>You can also set <code>interval: &#39;500ms&#39;</code> at the root of the Taskfile. The interval groups events close together so that Task reruns the task once for the batch.</p><h2 id="watch-long-running-apps" tabindex="-1">Watch long-running apps <a class="header-anchor" href="#watch-long-running-apps" aria-label="Permalink to &quot;Watch long-running apps&quot;">​</a></h2><p>Builds and checks finish after each run. Servers keep running and need to stop before a replacement can take over their port.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>There is a <a href="https://github.com/go-task/task/issues/160" target="_blank" rel="noreferrer">known issue</a> where watch mode may leave child processes running. Prefer building and running the executable directly over <code>go run</code>, which starts another process.</p></div><p>For applications that need dedicated live-reload behavior, consider tools such as <a href="https://github.com/air-verse/air/" target="_blank" rel="noreferrer">Air</a>. Report Task-specific problems with a small reproducer in the <a href="https://github.com/go-task/task/issues/new?template=bug_report.yml" target="_blank" rel="noreferrer">issue tracker</a>.</p>`,17)])])}const g=a(n,[["render",h]]);export{k as __pageData,g as default};
